    final String localPlanNodeId = "fragmentSink_0";
    final TFragmentInstanceId localFragmentInstanceId = new TFragmentInstanceId(queryId, 1, "0");
    // Construct a mock LocalMemoryManager that returns unblocked futures.
    LocalMemoryManager mockLocalMemoryManager = Mockito.mock(LocalMemoryManager.class);
    MemoryPool mockMemoryPool = Utils.createMockNonBlockedMemoryPool();
    Mockito.when(mockLocalMemoryManager.getQueryPool()).thenReturn(mockMemoryPool);
    IClientManager<TEndPoint, SyncDataNodeMPPDataExchangeServiceClient> mockClientManager = Mockito.mock(IClientManager.class);
    // Construct a mock client.
    SyncDataNodeMPPDataExchangeServiceClient mockClient = Mockito.mock(SyncDataNodeMPPDataExchangeServiceClient.class);
    try {
        Mockito.when(mockClientManager.borrowClient(remoteEndpoint)).thenReturn(mockClient);
        Mockito.doNothing().when(mockClient).onEndOfDataBlockEvent(Mockito.any(TEndOfDataBlockEvent.class));
        Mockito.doNothing().when(mockClient).onNewDataBlockEvent(Mockito.any(TNewDataBlockEvent.class));
    } catch (ClientManagerException | TException e) {
        e.printStackTrace();
        Assert.fail();
    }
    // Construct a mock SinkHandleListener.
    SinkHandleListener mockSinkHandleListener = Mockito.mock(SinkHandleListener.class);
    // Construct several mock TsBlock(s).
    List<TsBlock> mockTsBlocks = Utils.createMockTsBlocks(numOfMockTsBlock, mockTsBlockSize);
    // Construct SinkHandle.
    SinkHandle sinkHandle = new SinkHandle(remoteEndpoint, remoteFragmentInstanceId, remotePlanNodeId, localPlanNodeId, localFragmentInstanceId, mockLocalMemoryManager, Executors.newSingleThreadExecutor(), Utils.createMockTsBlockSerde(mockTsBlockSize), mockSinkHandleListener, mockClientManager);
    Assert.assertTrue(sinkHandle.isFull().isDone());
    Assert.assertFalse(sinkHandle.isFinished());
    Assert.assertFalse(sinkHandle.isAborted());
    Assert.assertEquals(DEFAULT_MAX_TSBLOCK_SIZE_IN_BYTES, sinkHandle.getBufferRetainedSizeInBytes());
    Assert.assertEquals(0, sinkHandle.getNumOfBufferedTsBlocks());
    // Send tsblocks.
    sinkHandle.send(mockTsBlocks.get(0));
    Assert.assertTrue(sinkHandle.isFull().isDone());
    Assert.assertFalse(sinkHandle.isFinished());
    Assert.assertFalse(sinkHandle.isAborted());
    Assert.assertEquals(mockTsBlockSize * numOfMockTsBlock + DEFAULT_MAX_TSBLOCK_SIZE_IN_BYTES, sinkHandle.getBufferRetainedSizeInBytes());
    Assert.assertEquals(numOfMockTsBlock, sinkHandle.getNumOfBufferedTsBlocks());
    //    Mockito.verify(mockMemoryPool, Mockito.timeout(10_0000).times(1))
    //        .reserve(
    //            queryId,
    //            localFragmentInstanceId.getInstanceId(),
    //            localPlanNodeId,
    //            mockTsBlockSize * numOfMockTsBlock,
    //            Long.MAX_VALUE);
    try {
        Mockito.verify(mockClient, Mockito.timeout(10_000).times(1)).onNewDataBlockEvent(Mockito.argThat(e -> remoteFragmentInstanceId.equals(e.getTargetFragmentInstanceId()) && remotePlanNodeId.equals(e.getTargetPlanNodeId()) && localFragmentInstanceId.equals(e.getSourceFragmentInstanceId()) && e.getStartSequenceId() == 0 && e.getBlockSizes().size() == numOfMockTsBlock));
    } catch (TException e) {
        e.printStackTrace();
        Assert.fail();
    }
    // Get tsblocks.
    for (int i = 0; i < numOfMockTsBlock; i++) {
        try {
            sinkHandle.getSerializedTsBlock(i);
        } catch (IOException e) {
            e.printStackTrace();
            Assert.fail();
        }
        Assert.assertTrue(sinkHandle.isFull().isDone());
    }
    Assert.assertFalse(sinkHandle.isFinished());
    // Set no-more-tsblocks.
    sinkHandle.setNoMoreTsBlocks();
    Assert.assertTrue(sinkHandle.isFull().isDone());
    Assert.assertFalse(sinkHandle.isFinished());
    Assert.assertFalse(sinkHandle.isAborted());
    Mockito.verify(mockSinkHandleListener, Mockito.timeout(10_000).times(1)).onEndOfBlocks(sinkHandle);
    // Ack tsblocks.
    sinkHandle.acknowledgeTsBlock(0, numOfMockTsBlock);
    Assert.assertTrue(sinkHandle.isFull().isDone());
    Assert.assertTrue(sinkHandle.isFinished());
    Assert.assertFalse(sinkHandle.isAborted());
    Assert.assertEquals(mockTsBlockSize, sinkHandle.getBufferRetainedSizeInBytes());
    Mockito.verify(mockMemoryPool, Mockito.timeout(10_0000).times(1)).free(queryId, localFragmentInstanceId.getInstanceId(), localPlanNodeId, numOfMockTsBlock * mockTsBlockSize);
    Mockito.verify(mockSinkHandleListener, Mockito.timeout(10_0000).times(1)).onFinish(sinkHandle);
    try {
        Mockito.verify(mockClient, Mockito.timeout(10_000).times(1)).onEndOfDataBlockEvent(Mockito.argThat(e -> remoteFragmentInstanceId.equals(e.getTargetFragmentInstanceId()) && remotePlanNodeId.equals(e.getTargetPlanNodeId()) && localFragmentInstanceId.equals(e.getSourceFragmentInstanceId()) && numOfMockTsBlock - 1 == e.getLastSequenceId()));
    } catch (TException e) {
        e.printStackTrace();
        Assert.fail();
    }
}

